<style>
    :root{--ar-navy:#0F274A;--ar-navy-soft:#183a68;--ar-gold:#C5A86D;--ar-gold-hover:#b8995f;--ar-cream:#F7F5F0;--ar-muted:#64748b}
    *{box-sizing:border-box} body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px;font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;color:var(--ar-navy);background:radial-gradient(ellipse 80% 60% at 10% 0%,rgba(197,168,109,.18),transparent 55%),radial-gradient(ellipse 70% 50% at 100% 100%,rgba(15,39,74,.08),transparent 50%),var(--ar-cream)}
    .ar-card{width:100%;max-width:460px;background:#fff;border:1px solid rgba(15,39,74,.08);border-radius:20px;box-shadow:0 16px 40px rgba(15,39,74,.1);padding:38px 36px;border-top:4px solid var(--ar-gold)}
    .ar-brand{text-align:center;margin-bottom:26px}.ar-logo{width:68px;height:68px;object-fit:contain;margin:0 auto 12px;display:block}.ar-title{font-size:1.55rem;line-height:1.2;margin:0;font-weight:750;letter-spacing:-.02em}.ar-sub{font-size:14px;line-height:1.55;color:var(--ar-muted);margin:8px 0 0}
    .ar-field{margin-bottom:16px}.ar-label{display:block;font-size:12px;font-weight:650;margin-bottom:6px}.ar-input-wrap{display:flex;align-items:center;background:#edf2f7;border:1px solid transparent;border-radius:12px;overflow:hidden;transition:.2s}.ar-input-wrap:focus-within{background:#fff;border-color:var(--ar-gold);box-shadow:0 0 0 3px rgba(197,168,109,.2)}.ar-input-wrap.is-invalid{border-color:#dc2626}.ar-icon{padding:0 14px;color:var(--ar-muted)}.ar-input{width:100%;border:0;outline:0;background:transparent;padding:13px 14px 13px 0;color:var(--ar-navy);font:inherit;font-size:15px}.ar-eye{border:0;background:transparent;padding:0 14px;color:var(--ar-muted);cursor:pointer}.ar-error{font-size:13px;color:#dc2626;margin:6px 0 0}.ar-status{font-size:13px;padding:11px 13px;border-radius:10px;background:#ecfdf5;color:#166534;border:1px solid #bbf7d0;margin-bottom:16px}
    .ar-btn{width:100%;display:flex;align-items:center;justify-content:center;gap:8px;border:0;border-radius:12px;padding:13px 20px;background:var(--ar-navy);color:#fff;font:inherit;font-size:14px;font-weight:700;cursor:pointer}.ar-btn:hover{background:var(--ar-navy-soft)}.ar-foot{text-align:center;border-top:1px solid rgba(15,39,74,.08);margin-top:24px;padding-top:17px;font-size:13px;color:var(--ar-muted)}.ar-link{color:var(--ar-gold-hover);font-weight:650;text-decoration:none}.ar-link:hover{color:var(--ar-navy)}.ar-hint{font-size:12px;line-height:1.5;color:var(--ar-muted);margin:-7px 0 16px}
    @media(max-width:480px){.ar-card{padding:30px 22px}}
</style>
